={{ {
  "model": "ollama/deepseek-coder-v2:16b",
  "messages": [
    {
      "role": "system",
      "content": "You are an expert code reviewer. Analyze code for: 1) Bugs and potential issues, 2) Security vulnerabilities, 3) Performance optimizations, 4) Best practices, 5) Code style. Provide specific, actionable feedback."
    },
    {
      "role": "user",
      "content": "Review this code:\n\n" + $json.body.code + "\n\nLanguage: " + ($json.body.language || "unknown")
    }
  ],
  "temperature": 0.3
} }}

parameters.jsCode:
// Extract and structure the review
const review = items[0].json.choices[0].message.content;
const originalCode = items[0].json.body?.code || '';
const language = items[0].json.body?.language || 'unknown';

return {
  json: {
    language: language,
    review: review,
    timestamp: new Date().toISOString(),
    model: items[0].json.model,
    codeLength: originalCode.length
  }
};
